$string['panel_bychannel_foot'] = 'Como se conta: a origem é o primeiro contato medido e não muda depois. Uma jornada, uma ligação ou o cartaz da porta são portas, nunca a origem, e um anúncio só conta se a família era nova. O perfil no Google, por utm_medium=ficha; a publicidade, por um meio pago (cpc, paid, ads, campaign); os e-mails e mensagens da escola, por email, newsletter ou sms; os impressos, por qr ou impreso; as redes, por social ou por vir de uma rede; o site da escola, pelo domínio do seu e-mail ou pelos seus formulários. Sem nada medido, conta o que a família disse em «Como nos conheceram?»; se também não disse, vai para «Sem medição» e não é atribuída a ninguém. Nenhum canal leva mais do que o medido: um anúncio visto sem clicar não deixa rastro e pode acabar em uma busca ou em uma visita direta ao site, e quem deixa o contato em um anúncio pode ter conhecido a escola antes. Quem são sai das listas da escola, do que dizem as famílias e a equipe, e da lista de ex-alunos.';
