$string['panel_isthis_bridge'] = 'Uma ponte traz para o Eguahe o que chega por outra ferramenta (os anúncios do Google ou da Meta, a caixa de admissões ou um formulário que a escola já usa), para que cada família tenha a sua ficha e seja respondida pela caixa de entrada.';
$string['panel_isthis_entries'] = 'Uma entrada é um lugar por onde as famílias chegam: o formulário do site da escola, um QR em um cartaz, a caixa de admissões ou os anúncios do Google ou da Meta. Cada família que chega por uma delas conta como uma chegada, e aqui se vê qual traz mais.';
