$string['panel_voice_channel_def'] = 'De onde vêm de verdade: o primeiro contato medido de cada família, nunca a jornada ou o formulário por onde entrou, e também com as que se perderam. Primeiro, os canais da própria escola (seu site, os buscadores, os assistentes de IA, seu perfil no Google, suas redes, seus e-mails e mensagens, e o boca a boca); depois, a publicidade; depois, outros caminhos (impressos e QR, outros sites, sem passar pelo site), e no fim o que não foi medido. Cada canal, com até onde suas famílias chegaram e quem são: as novas de verdade, as que já eram da escola (que não contam no resto dos números), as que já tiveram filhos nela e as de ex-alunos.';
